struct Node;

/// Truncate to at most `max` characters on a char boundary. The `requires`
/// clause already bounds the input question to 512, but we re-establish the
/// `ensures len(question) <= 512` postcondition locally rather than trusting it.
fn bound(mut s: String, max: usize) -> String {
    if s.chars().count() > max {
        let end = s
            .char_indices()
            .nth(max)
            .map(|(i, _)| i)
            .unwrap_or(s.len());
        s.truncate(end);
    }
    s
}

